def _input_check_options(enabled: bool, append: bool, hotkey: bool, retries: int, expected: str) -> dict[str, Any]:
    if not enabled:
        return {}
    if (append or hotkey) and expected == "":
        raise InvalidParamsError("追加输入或包含快捷键时，输入验证必须提供 check_value")
    if not isinstance(retries, int) or isinstance(retries, bool) or retries < 0:
        raise InvalidParamsError("retry_times 必须是非负整数")
    retries = 0 if append else retries
    return {
        "input_check": True, "retry_times": retries, "check_value": expected,
        "timeout": 15.3 * (retries + 1) + 2 * retries,
    }

@_with_manual_motion
def web_type_text_element(self, params: dict[str, Any]) -> dict[str, Any]:
    if not _truthy(params.get("input_check"), default=False):
        return self._run_web_dom_action(params, action="type_text")
    retries = params.get("retry_times", 3)
    expected = str(params.get("check_value") or "")
    append = not _truthy(params.get("clear"), default=False)
    if ((append or _truthy(params.get("contains_hotkey"), default=False)) and not expected
            or not isinstance(retries, int) or isinstance(retries, bool) or retries < 0):
        return _action_result(business_error(2, "invalid_params", message="输入验证参数无效，请检查 check_value 和 retry_times"))
    retries = 0 if append else retries
    expected = (expected or str(params.get("text") or "")).replace("\r\n", "\n").replace("\r", "\n")
    deadline = time.monotonic() + max(0, _int_param(params.get("timeout_ms"), 10000)) / 1000
    for attempt in range(retries + 1):
        remaining = int((deadline - time.monotonic()) * 1000)
        if remaining <= 300:
            return _action_result(business_error(5, "request_timeout", message="输入验证超时"))
        result = self._run_web_dom_action({**params, "timeout_ms": min(10000, remaining)}, action="type_text")
        if _int_param(result.get("error"), 5) != 0:
            return result
        if deadline - time.monotonic() < 0.3:
            return _action_result(business_error(5, "request_timeout", message="输入验证超时"))
        time.sleep(0.3)
        remaining = int((deadline - time.monotonic()) * 1000)
        if remaining <= 0:
            return _action_result(business_error(5, "request_timeout", message="输入验证超时"))
        read = self._run_web_value({**params, "mode": "input_check", "timeout_ms": min(5000, remaining)}, op="get_value")
        if _int_param(read.get("error"), 5) != 0:
            return read
        if time.monotonic() >= deadline:
            return _action_result(business_error(5, "request_timeout", message="输入验证超时"))
        actual = read.get("value")
        if actual is not None and str(actual).replace("\r\n", "\n").replace("\r", "\n") == expected:
            return result
        if attempt == retries:
            actual_text = "（无值）" if actual is None else str(actual)
            return _action_result(business_error(
                5, "input_check_failed",
                message=f"输入内容验证失败，输入后预期文本为：{expected}，实际文本为：{actual_text}",
            ))
        if deadline - time.monotonic() < 2:
            return _action_result(business_error(5, "request_timeout", message="输入验证超时"))
        time.sleep(2)
    raise AssertionError("input verification loop must return")

def _run_web_type_text_with_text_backend_if_needed(
    self,
    params: dict[str, Any],
    desc: dict[str, Any],
    *,
    timeout_ms: int,
) -> dict[str, Any] | None:
    mode = str(params.get("mode") or "dom").strip().casefold()
    if mode not in {"dom", "set_value", "cdp", "keyboard", "clipboard"}:
        return _action_result(business_error(2, "invalid_params", message="文本输入模式无效"), strategy="web_type_text")
    if mode == "cdp":
        return None
    if desc.get("silent_running", False) and mode != "clipboard":
        if _truthy(params.get("contains_hotkey"), default=False):
            return _action_result(
                business_error(2, "unsupported_action", message="静默填写暂不支持快捷键，请显式使用极速直写"),
                strategy="web_dom",
            )
        return None
    if mode in {"dom", "set_value"}:
        return None

if action == "type_text":
    payload["text"] = str(params.get("text") or "")
    payload["clear"] = _truthy(params.get("clear"), default=False)
    payload["focus"] = _truthy(params.get("focus"), default=True)
    if str(params.get("mode") or "").strip().casefold() == "cdp":
        payload["contains_hotkey"] = _truthy(params.get("contains_hotkey"), default=False)
        if payload["contains_hotkey"]:
            payload["text"] = _normalize_send_keys_expression(payload["text"])
        payload["send_key_delay_ms"] = max(0, _int_param(params.get("send_key_delay_ms"), 50))
if action in {"click", "double_click", "hover"}:
    payload["mode"] = pointer_mode
elif action == "check" or "mode" in params:
    payload["mode"] = str(params.get("mode") or action).strip().casefold()
if action == "type_text" and desc.get("silent_running", False) and payload.get("mode") == "keyboard":
    payload["mode"] = "dom"

function dispatchTextInputEvents(element, value) {
  dispatchEventType(element, "beforeinput", { data: value == null ? null : String(value), inputType: "insertText" }, "InputEvent");
  dispatchEventType(element, "input", { data: value == null ? null : String(value), inputType: "insertText" }, "InputEvent");
  dispatchEventType(element, "change", {}, "Event");
}

function setNativeElementProperty(element, property, value) {
  if (!element || typeof element !== "object") return false;
  try {
    const proto = Object.getPrototypeOf(element);
    const descriptor = proto ? Object.getOwnPropertyDescriptor(proto, property) : null;
    if (descriptor && typeof descriptor.set === "function") {
      descriptor.set.call(element, value);
      return true;
    }
  } catch (_error) {}
  try {
    element[property] = value;
    return true;
  } catch (_error) {
    return false;
  }
}

function setEditableText(element, text) {
  const value = String(text == null ? "" : text);
  if (element.isContentEditable) {
    try {
      element.textContent = value;
      if ("innerText" in element) element.innerText = value;
      return true;
    } catch (_error) {
      return false;
    }
  }
  if ("value" in element) return setNativeElementProperty(element, "value", value);
  return false;

if (command.mode === "cdp") {
  const input = webInputElement(element, true);
  if (!input || input.disabled || input.readOnly) return { ok: true, result: webDomResult(3, "element_not_editable") };
  if (command.focus !== false) input.focus();
  if (!input.isConnected || input.getRootNode().activeElement !== input) {
    return { ok: true, result: webDomResult(3, "element_not_focused") };
  }
  let appendWithKeys = false;
  if (input.isContentEditable) {
    const range = input.ownerDocument.createRange();
    range.selectNodeContents(input);
    if (!command.clear) range.collapse(false);
    const selection = input.ownerDocument.getSelection();
    selection.removeAllRanges();
    selection.addRange(range);
  } else if (command.clear) {
    input.select();
  } else if (/^(number|email)$/.test(input.type)) {
    appendWithKeys = true;
  } else {
    const length = String(input.value ?? "").length;
    input.setSelectionRange(length, length);
  }
  return { ok: true, result: webDomResult(0, "", {
    input_ref: liveElementDescriptor(input).element_ref, input_append_with_keys: appendWithKeys,
  }) };
}
const text = String(command.text ?? "");
const tag = String(element.nodeName || element.tagName || "").toLowerCase();
const property = command.mode === "set_value" || tag === "input" || tag === "textarea" ? "value" : "innerText";
const value = command.mode === "set_value" || command.clear ? text : String(element[property] ?? "") + text;
if (command.mode === "set_value") {
  element[property] = value;
} else {
  // Bypass instance value trackers so controlled forms observe the input event.
  if (!setNativeElementProperty(element, property, value)) {
    return { ok: true, result: webDomResult(3, "element_not_editable", selectorExtras) };
  }
  dispatchTextInputEvents(element, text);
}
return { ok: true, result: webDomResult(0, "", selectorExtras) };

async function runCdpWebDomCommand(cmd) {
  let textSteps;
  if (cmd.action === 'type_text') {
    try {
      textSteps = compileCdpText(String(cmd.text ?? ''), cmd.contains_hotkey === true);
      if (cmd.contains_hotkey === true && cmd.clear) textSteps.unshift({ text: '' });
    }
    catch (error) { return { handled: true, message: webDomCompletionMessage(cmd.requestId,
      webDomResult(2, error.message === 'unsupported_cdp_key' ? 'unsupported_cdp_key' : 'invalid_hotkey_expression')) }; }
  }
  const prepared = await prepareWebDomOperation(cmd);
  if (!prepared.operation) return prepared;
  const initial = prepared.operation;
  const deadlineMs = Number(cmd.deadlineMs || cmd.adapterDeadlineMs) || Date.now() + timeoutMs(cmd, 10000);
  initial.options.adapterDeadlineMs = deadlineMs;
  try {
    if (deadlineMs <= Date.now()) throw new Error('request_timeout');
    const lease = globalThis.UIAutomaWebEngineDebuggerLease;
    if (!lease) throw new Error('debugger_attach_unavailable');
    const result = await lease.withTab(initial.tabId, async (target, api) => {
      const router = globalThis.UIAutomaWebEnginePageRuntimeRouter;
      const response = await router.ensureAndInvoke(initial.tabId, initial.frameId, initial.package,
        initial.command, initial.options);
      const routed = await continueWebDomRoute(initial, response);
      if (routed.result) return routed.result;
      const operation = routed.operation;
      const geometry = mapWebDomOperationResponse(routed.response);
      if (Number(geometry.error) !== 0) return geometry;
      if (cmd.action === 'type_text') {
        if (!geometry.input_ref) throw new Error('stale_element_reference');
        if (deadlineMs <= Date.now()) throw new Error('request_timeout');
        const checked = mapWebDomOperationResponse(await router.ensureAndInvoke(operation.tabId,
          operation.frameId, operation.package, { type: 'web.dom', action: 'get_value',
            mode: 'cdp_ready', element_ref: geometry.input_ref }, operation.options));
        if (Number(checked.error) !== 0) return checked;
        const remaining = deadlineMs - Date.now();
        if (remaining <= 0) throw new Error('request_timeout');
        if (geometry.input_append_with_keys === true) {
          textSteps.unshift(...compileCdpText('{Ctrl}{End}', true));
        }
        await sendCdpText(textSteps, target, api, deadlineMs, cmd.contains_hotkey ? Math.max(0, Number(cmd.send_key_delay_ms) || 0) : 0);
        return webDomResult(0, '', { strategy: 'web_cdp' });
